export class ManagedResource {
    label;
    disposed = false;
    constructor(label) {
        this.label = label;
    }
    dispose() {
        if (this.disposed)
            return;
        this.disposed = true;
        this.release();
    }
    assertAlive() {
        if (this.disposed) {
            throw new Error(`${this.constructor.name}${this.label ? ` (${this.label})` : ''} is disposed.`);
        }
    }
}